const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function buffPanelMarkup(selection,buffResult,buffRules,{title='Активные баффы',detailsId='dps-active-buffs',open=false}={}){
  const buffNames={experience:'Опыт',silver:'Серебро',dropChance:'Шанс предметов',defense:'Защита',resistance:'Сопротивление',attack:'Атака',physicalAttack:'Физ. атака',magicAttack:'Маг. атака',magicExtra:'Доп. маг. урон',hp:'Здоровье',evasion:'Уклонение',movementSpeed:'Скорость движения',haste:'Скорость атаки и активации',healthRegen:'Регенерация HP',manaRegen:'Регенерация маны'};
  const bonusesText=bonuses=>Object.entries(bonuses).map(([k,v])=>`${buffNames[k]||k}: +${v}${k.endsWith('Regen')?'/с':'%'}`).join(' · ');
  const buffRow=(key,label,choices)=>`<div class="dps-buff-row"><span>${label}</span><div role="group" aria-label="${label}">${choices.map(([value,title])=>`<button class="secondary" data-buff-choice="${key}" data-value="${value}" aria-pressed="${String(selection[key])===String(value)}" title="${key==='heroes'?'':escape(bonusesText(buffRules.fortune[value]||{}))}">${title}</button>`).join('')}</div></div>`;
  return `<section class="panel dps-buffs"><h2>${escape(title)}</h2>${buffRow('heroes','Баффы героев',[['none','Без баффов'],['house','Домик'],['fountain','Фонтан']])}${buffRow('prosperity','Процветание',[[0,'Нет'],[1,'1 лвл'],[2,'2 лвл'],[3,'3 лвл']])}${buffRow('casino','Казик',[[0,'Нет'],[1,'1 лвл'],[2,'2 лвл'],[3,'3 лвл']])}<small>Три группы складываются. Баффы из настроек персонажа сохраняются.</small>${buffResult.details.length?`<details id="${escape(detailsId)}" ${open?'open':''}><summary>Активные бонусы</summary>${buffResult.details.map(d=>`<p><strong>${escape(d.name)} · ${d.level} ур.${d.estimated?' ≈':''}</strong><br>${escape(bonusesText(d.bonuses))}</p>`).join('')}</details>`:''}</section>`;
}
